import { ApiResponse, ResponseBody } from "./domain/responseBody";
import { ResponseService } from "./ResponseService";

export class ResponseServiceIpml implements ResponseService {
    private buildResponse(statusCode: number, body: ResponseBody = {}): ApiResponse {
        return {
            statusCode,
            headers: {
                "Access-Control-Allow-Origin": "*",
                "Access-Control-Allow-Credentials": true,
                "Access-Control-Max-Age": 300,
            },
            body: JSON.stringify(body),
        };
    }

    public success(body: ResponseBody): ApiResponse {
        return this.buildResponse(200, body);
    }

    public clientError(errorMessage: string): ApiResponse {
        const body = {
            status: false,
            errorMessage,
        };
        return this.buildResponse(400, body);
    }

    public clientErrors(errors: string[]): ApiResponse {
        const body = {
            status: false,
            errorMessages: errors,
        };
        return this.buildResponse(400, body);
    }

    public failure(body: ResponseBody): ApiResponse {
        return this.buildResponse(500, body);
    }
};
